class CompactStateDecoderTest {
    @Test
    fun `producer CVS1 fixtures retain zero speed GPS accepted navigation and alerts`() {
        // Given: fixtures generated by artifact compact_state.py encode_carrot_state_frame.
        val store = CompactTelemetryStore()
        // When
        val snapshot = store.accept(fixtures.values.flatMap { CompactStateDecoder.decode(hex(it)) }, 1000)
        val vehicle = snapshot.toVehicleData(123)!!
        // Then
        assertThat(snapshot.services.keys).containsExactlyElementsIn(CompactStateDecoder.supportedServices)
        snapshot.services.values.forEach {
            assertWithMessage(it.frame.service).that(it.frame.unknownTrailingBytes).isEqualTo(0)
        }
        assertThat(vehicle.carState!!.vEgo).isEqualTo(0f)
        assertThat(vehicle.carState!!.steeringAngleDeg).isEqualTo(-12.5f)
        assertThat(vehicle.carState!!.leftBlindspot).isTrue()
        assertThat(vehicle.carState!!.leftLatDist.isNaN()).isTrue()
        assertThat(vehicle.controlsState!!.vCruise).isEqualTo(20f)
        assertThat(vehicle.controlsState!!.active).isFalse()
        assertThat(vehicle.selfdriveState!!.active).isFalse()
        val gps = snapshot.fresh("gpsLocationExternal")!!.frame.values
        assertThat(gps["latitude"] as Double).isWithin(0.000001).of(31.2)
        assertThat(gps["longitude"] as Double).isWithin(0.000001).of(121.4)
        assertThat(gps["speed"]).isEqualTo(0f)
        assertThat(gps["horizontalAccuracy"]).isEqualTo(3f)
        assertThat(snapshot.carrotMan!!.desiredSpeedKph).isEqualTo(60)
        assertThat(snapshot.carrotMan!!.desiredSource).isEqualTo("cam")
        assertThat(snapshot.carrotMan!!.roadLimitKph).isEqualTo(80)
        assertThat(snapshot.carrotMan!!.speedDistanceM).isEqualTo(300)
        assertThat(snapshot.carrotMan!!.speedCountdownSec).isEqualTo(9)
        assertThat(snapshot.carrotMan!!.turnCountdownSec).isEqualTo(5)
        assertThat(vehicle.carrotMan!!["szSdiDescr"]).isEqualTo("Camera")
        assertThat(snapshot.fresh("selfdriveState")!!.frame.values["alertText2"]).isEqualTo("立即接管")
        assertThat(snapshot.fresh("selfdriveState")!!.frame.values["alertStatus"]).isEqualTo("critical")
        assertThat(snapshot.carrotNavi!!.generation).isEqualTo(17uL)
        assertThat(snapshot.carrotNavi!!.guidanceCurrent!!["mainText"]).isEqualTo("Left")
        assertThat(snapshot.carrotNavi!!.speed!!["sdiSpeedLimitKph"]).isEqualTo(60)
        assertThat(snapshot.carrotNavi!!.trafficSignal!!["redRemainSec"]).isEqualTo(12)
        assertThat(snapshot.fresh("lateralPlan")!!.frame.values["laneChangeState"]).isEqualTo("preLaneChange")
        assertThat(snapshot.fresh("carControl")!!.frame.values["latActive"]).isEqualTo(true)
        assertThat(snapshot.fresh("longitudinalPlan")!!.frame.values["longitudinalPlanSource"]).isEqualTo("lead0")
        val details = snapshot.toDisplaySnapshot()
        assertThat(details.vehicleMotion!!.gear).isEqualTo("drive")
        assertThat(details.vehicleMotion!!.accelerationMps2).isEqualTo(0f)
        assertThat(details.planning).isEqualTo(ReceivedPlanning(0f, -0.5f))
        assertThat(details.actuation).isEqualTo(ReceivedActuation(2f, -1f))
        assertThat(details.laneLinesUsed).isTrue()
        assertThat(details.leftLead).isEqualTo(ReceivedLead(12f, 3.6f))
        assertThat(details.rightLead).isNull()
        val coordinates = snapshot.carrotNavi!!.route!!["polyline"] as List<*>
        assertThat(coordinates).hasSize(2)
        val last = coordinates.last() as Map<*, *>
        assertThat(last["latitude"] as Double).isWithin(0.00000001).of(31.2001)
        assertThat(last["longitude"] as Double).isWithin(0.00000001).of(121.4002)
    }

    @Test
    fun `CVB1 batch has exact unsigned frame lengths and all or nothing validation`() {
        // Given
        val frames = listOf(hex(fixtures.getValue("carState")), hex(fixtures.getValue("carrotMan")))
        val batch = batch(frames)
        // When
        val decoded = CompactStateDecoder.decode(batch)
        // Then
        assertThat(decoded.map { it.service }).containsExactly("carState", "carrotMan").inOrder()
        assertThat(decoded.map { it.sequence }).containsExactly(65535, 65535)
        assertMalformed(batch.copyOf(batch.size - 1))
        assertMalformed(batch + byteArrayOf(0))
        val negativeLength = batch.copyOf().also { ByteBuffer.wrap(it).order(ByteOrder.LITTLE_ENDIAN).putInt(6, -1) }
        assertMalformed(negativeLength)
        assertMalformed(hex("435642310100080000004356423100000000"))
        assertThat(CompactStateDecoder.decode(batch(emptyList()))).isEmpty()
    }

    @Test
    fun `strict bounds reject partial required fields lists texts booleans enums and nonfinite floats`() {
        // Given
        val car = hex(fixtures.getValue("carState"))
        // When / Then
        for (length in 0 until car.size - 2) assertMalformed(car.copyOf(length))
        assertMalformed(car.copyOf().also { it[5] = 1 })
        assertMalformed(car.copyOf().also { it[4] = 99 })
        assertMalformed(car.copyOf().also { it[28] = 2 }) // brakeHoldActive
        assertMalformed(car.copyOf().also { it[46] = 127 }) // gear enum
        assertMalformed(car.copyOf().also { ByteBuffer.wrap(it).order(ByteOrder.LITTLE_ENDIAN).putFloat(8, Float.NaN) })
        assertMalformed(hex(fixtures.getValue("carrotMan")).copyOf(55)) // incomplete text
        assertMalformed(hex("43565331030000000000000000ffff")) // CPU list overruns body
        assertMalformed(hex("435653310c000000010100ff")) // invalid UTF-8 latDebugText
        val navi = hex(fixtures.getValue("carrotNavi"))
        assertMalformed(navi.copyOf().also { it[it.size - 28] = 65 }) // coord_list exceeds the producer's 64 point cap
        assertMalformed(ByteArray(CompactStateDecoder.MAX_MESSAGE_BYTES + 1))
    }

    @Test
    fun `only documented trailing fields may be missing and future appended bytes are tolerated`() {
        // Given
        val car = hex(fixtures.getValue("carState"))
        val gps = hex(fixtures.getValue("gpsLocationExternal"))
        // When
        val oldCar = CompactStateDecoder.decode(car.copyOf(car.size - 2)).single()
        val oldGps = CompactStateDecoder.decode(gps.copyOf(41)).single()
        val future = CompactStateDecoder.decode(car + byteArrayOf(42, 0, 0)).single()
        // Then
        assertThat(oldCar.values).doesNotContainKey("evModeValid")
        assertThat(oldCar.values["vEgo"]).isEqualTo(0f)
        assertThat(oldGps.values["hasFix"]).isEqualTo(true)
        assertThat(oldGps.values).doesNotContainKey("horizontalAccuracy")
        assertThat(future.unknownTrailingBytes).isEqualTo(3)
        assertMalformed(gps.copyOf(42)) // partial altitude is not an older field boundary
    }

    @Test
    fun `model absolute velocity and radar relative velocity remain distinct and stale ego is not used`() {
        // Given
        val store = CompactTelemetryStore()
        val car = CompactStateDecoder.decode(hex(fixtures.getValue("carState")))
        val model = CompactStateDecoder.decode(hex(fixtures.getValue("modelV2")))
        val radar = CompactStateDecoder.decode(hex(fixtures.getValue("radarState")))
        // When
        val snapshot = store.accept(car + model + radar, 1000)
        // Then
        assertThat(snapshot.toVehicleData(123)!!.modelV2!!.leadV).isEqualTo(18f)
        assertThat(snapshot.toVehicleData(123)!!.modelV2!!.leadX).isEqualTo(25f)
        assertThat(snapshot.toVehicleData(123)!!.modelV2!!.orientationRate.isNaN()).isTrue()
        assertThat(snapshot.radarLead("leadOne")!!.relativeSpeedMps).isEqualTo(-2f)
        assertThat(snapshot.radarLead("leadOne")!!.estimatedAbsoluteSpeedMps).isEqualTo(-2f)
        assertThat(snapshot.radarLead("leadRight")).isNull()
        assertThat(snapshot.radarLead("leadLeft")!!.relativeSpeedMps).isEqualTo(1f)
        assertThat(store.accept(radar.map { it.copy(sequence = 0) }, 1200)
            .radarLead("leadOne")!!.estimatedAbsoluteSpeedMps).isNull()
        assertThat(store.snapshot(1500).fresh("carState")).isNull()
        assertThat(store.snapshot(2000).radarLead("leadOne")).isNull()
    }

    @Test
    fun `per service expiry clears only expired data and unrelated messages do not revive it`() {
        // Given
        val store = CompactTelemetryStore()
        store.accept(CompactStateDecoder.decode(hex(fixtures.getValue("carState"))), 1000, 10000)
        // When
        val snapshot = store.accept(CompactStateDecoder.decode(hex(fixtures.getValue("carrotMan"))), 1500, 10500)
        // Then
        assertThat(snapshot.toVehicleData(123)!!.carState).isNull()
        assertThat(snapshot.carrotMan!!.desiredSource).isEqualTo("cam")
        assertThat(store.snapshot(1750).toVehicleData(10750)!!.timestamp).isEqualTo(10500)
        assertThat(store.snapshot(3000).toVehicleData(123)).isNull()
        store.clear()
        assertThat(store.snapshot(3000).services).isEmpty()
    }

    @Test
    fun `7000 display adapter retains lanes blinkers cruise units and never fabricates safety or model meta`() {
        // Given
        val store = CompactTelemetryStore()
        val frames = fixtures.values.flatMap { CompactStateDecoder.decode(hex(it)) }
        val snapshot = store.accept(frames, 1000, 10000)
        // When
        val display = snapshot.toVehicleData(123)!!.toDisplayVehicleData(300)
        // Then
        assertThat(display.receiveTime).isEqualTo(10000)
        assertThat(display.carState!!.leftBlinker).isEqualTo(snapshot.fresh("carState")!!.frame.values["leftBlinker"])
        assertThat(display.carState!!.rightBlinker).isEqualTo(snapshot.fresh("carState")!!.frame.values["rightBlinker"])
        assertThat(display.carState!!.leftLatDist.isNaN()).isTrue()
        assertThat(display.modelV2!!.laneLineProbs).hasSize(4)
        assertThat(display.modelV2!!.lead0!!.v).isEqualTo(18f)
        assertThat(display.modelV2!!.meta).isNull()
        assertThat(display.modelV2!!.curvature).isNull()
        assertThat(display.controlsState!!.vCruise).isWithin(0.0001f).of(72f)
        assertThat(display.controlsState!!.curvature).isWithin(0.0001f).of(0.02f)
        assertThat(display.controlsState!!.active).isFalse()
        assertThat(display.systemState!!.active).isFalse()
        assertThat(display.systemState!!.engageable).isFalse()
        assertThat(display.noaLaneLocalization).isNull()
        assertThat(display.noaBehaviorPlan).isNull()
        assertThat(display.tbtDist).isEqualTo(300)
        assertThat(store.snapshot(1750).toVehicleData(99999)!!.toDisplayVehicleData(0).modelV2).isNull()
        assertThat(store.snapshot(4000).toVehicleData(99999)).isNull()
    }

    @Test
    fun `GPS without fix stays unknown rather than substituting carrot coordinates`() {
        // Given
        val store = CompactTelemetryStore()
        val gps = hex(fixtures.getValue("gpsLocationExternal")).also { it[40] = 0 }
        // When
        val snapshot = store.accept(CompactStateDecoder.decode(gps), 1000)
        // Then
        assertThat(snapshot.toVehicleData(123)).isNull()
        assertThat(snapshot.fresh("gpsLocationExternal")!!.frame.values["hasFix"]).isEqualTo(false)
    }

    @Test
    fun `closed client and cancelled lifecycle cannot restart sockets`() {
        // Given
        val parentJob = SupervisorJob()
        val client = CarrotWsClient(CoroutineScope(Dispatchers.Unconfined + parentJob))
        val closed = CarrotWsClient()
        // When
        parentJob.cancel()
        closed.disconnect()
        closed.close()
        closed.close()
        // Then
        assertThrows(IllegalStateException::class.java) { client.connect("127.0.0.1") }
        assertThrows(IllegalStateException::class.java) { closed.connect("127.0.0.1") }
        assertThat(client.connectionState.value).isEqualTo(ConnectionState.DISCONNECTED)
        assertThat(closed.compactState.value.services).isEmpty()
        assertThat(closed.vehicleData.value).isNull()
    }

    private fun assertMalformed(bytes: ByteArray) {
        assertThrows(CompactDecodeException::class.java) { CompactStateDecoder.decode(bytes) }
    }

    private fun batch(frames: List<ByteArray>): ByteArray {
        val buffer = ByteBuffer.allocate(6 + frames.sumOf { it.size + 4 }).order(ByteOrder.LITTLE_ENDIAN)
        buffer.put("CVB1".toByteArray()).putShort(frames.size.toShort())
        frames.forEach { buffer.putInt(it.size).put(it) }
        return buffer.array()
    }
    private fun hex(value: String) = value.chunked(2).map { it.toInt(16).toByte() }.toByteArray()

